DO $$ DECLARE d text;old text;replacement text;BEGIN d:=pg_get_functiondef('files.guard_attachment()'::regprocedure);old:='IF TG_OP=''UPDATE'' AND current_user=''app_domain'' AND NEW.unlinked_at IS DISTINCT FROM OLD.unlinked_at AND NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type=''files.unlink'' AND c.state=''claimed'') THEN RAISE EXCEPTION ''unlink command required'';END IF;';replacement:='IF current_user=''app_domain'' THEN IF TG_OP=''UPDATE'' AND NEW.unlinked_at IS DISTINCT FROM OLD.unlinked_at THEN IF NOT EXISTS(SELECT 1 FROM core.command_receipt c WHERE c.workspace_id=NEW.workspace_id AND c.id=NEW.command_receipt_id AND c.command_type=''files.unlink'' AND c.state=''claimed'') THEN RAISE EXCEPTION ''unlink command required'';END IF;END IF;END IF;';IF strpos(d,old)=0 THEN RAISE EXCEPTION 'role guard anchor missing';END IF;EXECUTE replace(d,old,replacement);END $$;